import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

def get_best_schedule(workload, num_seqs):
    """Decompose the read/write conflict graph, optimize each component, and verify joins."""
    import itertools
    import re
    import networkx as nx

    n = workload.num_txns
    if n <= 1:
        seq = list(range(n))
        return workload.get_opt_seq_cost(seq), seq

    # Workload implementations used by the benchmark expose transactions under
    # slightly different names.  If the representation cannot be recovered,
    # retaining one component is safe and falls back to normal global search.
    raw_txns = None
    for name in ("transactions", "txns", "workload", "txn_dict", "transaction_dict"):
        value = getattr(workload, name, None)
        if isinstance(value, dict) and len(value) == n:
            raw_txns = list(value.values())
            break
        if isinstance(value, (list, tuple)) and len(value) == n:
            raw_txns = list(value)
            break

    def accesses(txn):
        """Return (key, writes) pairs from common string and structured forms."""
        if isinstance(txn, str):
            values = [txn]
        elif isinstance(txn, (list, tuple)):
            values = txn
        else:
            values = None
            for name in ("operations", "ops", "operation_list"):
                candidate = getattr(txn, name, None)
                if candidate is not None:
                    values = candidate if isinstance(candidate, (list, tuple)) else [candidate]
                    break
            if values is None:
                values = [txn]

        found = []
        for op in values:
            if isinstance(op, (tuple, list)) and len(op) >= 2:
                kind, key = str(op[0]).lower(), str(op[1])
                if kind and kind[0] in ("r", "w"):
                    found.append((key, kind[0] == "w"))
                continue
            for kind, key in re.findall(r"([rRwW])[-_:]([^\s,\]\[()]+)", str(op)):
                found.append((key, kind.lower() == "w"))
        return found

    graph = nx.Graph()
    graph.add_nodes_from(range(n))
    parsed = raw_txns is not None
    by_key = {}
    if parsed:
        for txn_id, txn in enumerate(raw_txns):
            ops = accesses(txn)
            if not ops:
                parsed = False
                break
            # Multiple operations by one transaction on a key form only one
            # graph participant; any write makes its access conflicting.
            local = {}
            for key, is_write in ops:
                local[key] = local.get(key, False) or is_write
            for key, is_write in local.items():
                by_key.setdefault(key, []).append((txn_id, is_write))

    if parsed:
        for users in by_key.values():
            for left in range(len(users)):
                a, awrite = users[left]
                for right in range(left + 1, len(users)):
                    b, bwrite = users[right]
                    if awrite or bwrite:       # read/read is intentionally absent
                        graph.add_edge(a, b)
        components = [sorted(part) for part in nx.connected_components(graph)]
    else:
        components = [list(range(n))]

    cache = {}
    def cost(order):
        key = tuple(order)
        if key not in cache:
            cache[key] = workload.get_opt_seq_cost(order)
        return cache[key]

    def optimize_component(nodes):
        """Use exhaustive search for tiny components, then beam plus insertion descent."""
        m = len(nodes)
        if m <= 1:
            return nodes[:]
        if m <= 6:
            best = min(itertools.permutations(nodes), key=cost)
            return list(best)

        width = max(8, min(24, max(num_seqs, 8) * 2))
        beam = [(0, [], nodes[:])]
        for _ in range(m):
            expanded = []
            for _, prefix, remaining in beam:
                for txn in remaining:
                    candidate = prefix + [txn]
                    expanded.append((
                        cost(candidate), candidate,
                        [other for other in remaining if other != txn],
                    ))
            expanded.sort(key=lambda state: state[0])
            beam = expanded[:width]

        best_cost, best, _ = min(beam, key=lambda state: state[0])
        for _ in range(2):
            improved_cost, improved = best_cost, best
            for source, txn in enumerate(best):
                partial = best[:source] + best[source + 1:]
                for destination in range(m):
                    candidate = partial[:destination] + [txn] + partial[destination:]
                    candidate_cost = cost(candidate)
                    if candidate_cost < improved_cost:
                        improved_cost, improved = candidate_cost, candidate
            if improved_cost >= best_cost:
                break
            best_cost, best = improved_cost, improved
        return best

    # Isolated transactions consume no conflict-ordering search effort.
    components.sort(key=lambda part: (len(part) == 1, part[0]))
    ordered_parts = [optimize_component(part) for part in components]
    best_seq = [txn for part in ordered_parts for txn in part]
    best_cost = cost(best_seq)

    # Independent components should be interchangeable.  The real simulator is
    # nevertheless consulted for a small complete set of component joins, which
    # protects against any undocumented global scheduling behavior.
    nontrivial = [part for part in ordered_parts if len(part) > 1]
    isolated = [part for part in ordered_parts if len(part) == 1]
    if 1 < len(nontrivial) <= 6:
        for permutation in itertools.permutations(nontrivial):
            candidate = [txn for part in permutation + tuple(isolated) for txn in part]
            candidate_cost = cost(candidate)
            if candidate_cost < best_cost:
                best_cost, best_seq = candidate_cost, candidate
    elif len(nontrivial) > 1:
        candidate = [txn for part in reversed(nontrivial) + isolated for txn in part]
        candidate_cost = cost(candidate)
        if candidate_cost < best_cost:
            best_cost, best_seq = candidate_cost, candidate

    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")
